import { randomBytes } from "node:crypto";
import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import sharp from "sharp";

/** Slugs are generated by us and also come back from the URL, so validate them. */
const SLUG_PATTERN = /^[A-Za-z0-9_-]{10,24}$/;

/**
 * Channel teaser blur. Strong enough to hide details but keeps the silhouette
 * readable, which is what makes people open the app to see the real photo.
 */
const CHANNEL_BLUR_SIGMA = 22;

/** 18+ teasers get a stronger blur so the frame is not readable at all. */
const NSFW_BLUR_SIGMA = 32;

/** Keeps the channel upload small; Telegram rejects huge dimensions anyway. */
const CHANNEL_MAX_DIMENSION = 1600;

/** Telegram recommends video thumbnails no wider than 320px. */
const CHANNEL_THUMBNAIL_DIMENSION = 320;

export const MEDIA_EXTENSIONS = ["jpg", "mp4"] as const;
export type MediaExtension = (typeof MEDIA_EXTENSIONS)[number];

/**
 * Uploaded photos live outside the app directory on purpose: `npm run deploy`
 * rsyncs with --delete, which would wipe anything stored under /var/www/retpap.
 */
export function uploadDir(): string {
  const configured = process.env.UPLOAD_DIR?.trim();
  return configured && configured.length > 0 ? configured : path.join(process.cwd(), "data", "uploads");
}

export function mediaUrl(slug: string): string {
  return "/media/" + slug + ".jpg";
}

export function videoUrl(slug: string): string {
  return "/media/" + slug + ".mp4";
}

/** Absolute path for one stored file; null when the slug fails validation. */
export function mediaPath(slug: string, ext: MediaExtension): string | null {
  if (!SLUG_PATTERN.test(slug)) return null;
  return path.join(uploadDir(), slug + "." + ext);
}

async function writeMedia(slug: string, ext: MediaExtension, bytes: Buffer): Promise<void> {
  const dir = uploadDir();
  await mkdir(dir, { recursive: true });
  await writeFile(path.join(dir, slug + "." + ext), bytes, { flag: "wx" });
}

function newSlug(): string {
  return randomBytes(9).toString("base64url");
}

export async function savePhoto(bytes: Buffer): Promise<string> {
  const slug = newSlug();
  await writeMedia(slug, "jpg", bytes);
  return slug;
}

export async function saveVideo(bytes: Buffer): Promise<string> {
  const slug = newSlug();
  await writeMedia(slug, "mp4", bytes);
  return slug;
}

/** Stores the video poster under the same slug, so both files stay paired. */
export async function savePoster(slug: string, bytes: Buffer): Promise<void> {
  await writeMedia(slug, "jpg", bytes);
}

/**
 * Creates the blurred copy that goes to the channel. The feed and the uploader
 * always keep the original; this variant exists only as a teaser.
 */
export async function blurPhoto(
  bytes: Buffer,
  options: { nsfw?: boolean } = {},
): Promise<Buffer> {
  return sharp(bytes, { failOn: "none" })
    .rotate()
    .resize({
      width: CHANNEL_MAX_DIMENSION,
      height: CHANNEL_MAX_DIMENSION,
      fit: "inside",
      withoutEnlargement: true,
    })
    .blur(options.nsfw ? NSFW_BLUR_SIGMA : CHANNEL_BLUR_SIGMA)
    .jpeg({ quality: 82, mozjpeg: true })
    .toBuffer();
}

/**
 * Blurred video cover for the channel. Blur happens at full size first, then
 * the result is downscaled, so the perceived strength matches blurred photos.
 */
export async function blurredThumbnail(
  bytes: Buffer,
  options: { nsfw?: boolean } = {},
): Promise<Buffer> {
  return sharp(bytes, { failOn: "none" })
    .rotate()
    .resize({
      width: CHANNEL_MAX_DIMENSION,
      height: CHANNEL_MAX_DIMENSION,
      fit: "inside",
      withoutEnlargement: true,
    })
    .blur(options.nsfw ? NSFW_BLUR_SIGMA : CHANNEL_BLUR_SIGMA)
    .resize({
      width: CHANNEL_THUMBNAIL_DIMENSION,
      height: CHANNEL_THUMBNAIL_DIMENSION,
      fit: "inside",
      withoutEnlargement: true,
    })
    .jpeg({ quality: 80, mozjpeg: true })
    .toBuffer();
}
